for (int i = 0; i < 5; ++i) {
  for (int j = 0; j < 5; ++j) {
    pen p = black;
    if ((i == 0 && j == 0))      p = cCerulean;
    else if ((i == 2 && j == 3)) p = cCyan;
    else if ((i == 4 && j == 0)) p = cGray;
    else if ((i == 2 && j == 0)) p = cGray;
    else if ((i == 3 && j == 0)) p = cGray;
else if ((i == 1 && j == 0)) p = cGray;
    dot((i, j), p); 
